import{_ as r,c as l,o as t,ag as e}from"./chunks/framework.Bkod66qp.js";const g=JSON.parse('{"title":"회계규정","description":"","frontmatter":{"title":"회계규정","subtitle":"","doc_id":"","last_update":"2021-12-29","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/503_회계규정(211229).md","filePath":"regulation/503_회계규정(211229).md"}'),o={name:"regulation/503_회계규정(211229).md"};function i(s,a,n,c,h,d){return t(),l("div",null,a[0]||(a[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">회계규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;회계규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2004.   3.  12
개정 2004.   4.  27
개정 2006.   2.  21
개정 2007.  12.  21
개정 2008.   3.  28
개정 2009.   3.   9
개정 2010.   9.   1
개정 2011.   2.   1
개정 2014.   3.  31
개정 2014.  12.  29
개정 2015.   9.  21
개정 2016.   3.  29
개정 2016.  10.   7
개정 2018.  11.   1
개정 2018.  12.  28
개정 2019.  12.  30
개정 2021.  12.  29</pre></div><h2 id="제1장-총-칙" tabindex="-1">제1장 총 칙 <a class="header-anchor" href="#제1장-총-칙" aria-label="Permalink to &quot;제1장 총 칙&quot;">​</a></h2><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규정은 재단법인서울문화재단(이하“재단”이라 한다)의 정관에서 규정으로 정하도록 위임한 재단의 회계 및 재무에 관한 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (회계원칙) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (회계원칙) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(회계원칙)</strong> ➀ 재단의 회계는 재단의 재무상태와 사업성과 및 수지상황을 정확하게 나타낼 수 있도록 회계거래를 발생한 사실에 따라 공익법인회계기준에 의하여 처리하며, 이 기준에서 정하지 아니한 사항은 일반기업회계기준에 의하여 처리한다. 다만, 재단의 고유목적사업에 사용하기 위한 고유목적사업준비금은 결산조정으로 계상할 수 있다. &lt;개정 2007. 12. 21., 2018. 11. 01.&gt;<br> ➁ 재단의 회계처리는 다른 규정에 따로 정하여져 있는 것 외에는 이 규정이 정하는 바에 의한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (회계연도) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (회계연도) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(회계연도)</strong> 재단의 회계연도는 서울특별시 일반회계 연도에 의한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (회계의 구분) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (회계의 구분) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(회계의 구분)</strong> 재단의 회계는 수익사업회계와 비영리사업회계(고유목적사업회계)로 구분하며 사업별, 재산별로 각각 독립된 계정과목에 의하여 구분경리 하여야 한다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (용어의 정의) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (용어의 정의) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(용어의 정의)</strong> 재단의 회계는 대표이사가 관장하며 이 규정에서 사용하는 용어의 정의는 다음 각 호와 같다.</p><ol><li>“회계책임자”라 함은 재단전체의 회계 상황을 총체적으로 관리하며 필요하다고 판단되는 경우에는 소관부문에 대하여 지휘ㆍ감독을 할 수 있는 직위를 말한다.</li><li>“분임회계책임자”라 함은 회계책임자의 권한의 일부를 분장 받아 그 분장된 범위 안에서는 계약 및 지출에 관하여 독자적인 처리권한을 갖는 직위를 말한다.</li><li>“분임회계원”이라 함은 전도금을 포함한 소관부문의 회계에 대하여 회계책임자 또는 분임회계책임자의 권한의 일부를 행사 할 수 있는 직위를 말한다.</li><li>삭제 &lt;2014. 3. 31.&gt;</li><li>“출납담당자”라 함은 금전의 출납사무를 취급하는 자를 말한다.</li></ol><h2 id="article6" class="sr-only" tabindex="-1">제6조 (회계관계자 직명 지정) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (회계관계자 직명 지정) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(회계관계자 직명 지정)</strong> 대표이사는 회계업무수행을 위하여 다음 각 호와 같이 회계관계자 직명을 지정 운용한다.</p><ol><li>회계책임자 - 경영본부장 &lt;개정 2006. 2. 21., 2009. 3. 9., 2011. 2. 1., 2018. 12. 28., 2019. 12. 30.&gt;</li><li>분임회계책임자 - 회계부서의 장</li><li>분임회계원 - 회계담당자</li><li>전도금출납원 - 회계담당자</li><li>출납담당자 - 금전의 출납을 담당하는 직원</li></ol><h2 id="제2장-계정과목-및-회계장부" tabindex="-1">제2장 계정과목 및 회계장부 <a class="header-anchor" href="#제2장-계정과목-및-회계장부" aria-label="Permalink to &quot;제2장 계정과목 및 회계장부&quot;">​</a></h2><h2 id="article7" class="sr-only" tabindex="-1">제7조 (전표) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (전표) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(전표)</strong> ① 모든 거래는 거래발생부서의 전표에 의하여 회계부서에서 전표를 기표, 처리하며 회계장부는 전표에 따라 기장하여야 한다.<br> ② 전표에는 거래의 정당, 계산의 정확을 증명하는 영수증, 계산서 등의 증빙서류를 첨부하여야 한다.<br> ③ 전표의 종류는 입금전표, 출금전표 및 대체전표로 구분하되, 회계업무의 효율화를 기하기 위해 통합전표(1전표제) 또는 전표의 기능으로 대용할 수 있는 회계결의서를 사용할 수 있다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (계정과목) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (계정과목) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(계정과목)</strong> ① 계정과목은 재무상태표계정과 운영성과표계정으로 구분하고 그 과목은 내규의 정하는 바에 의한다. &lt;개정 2021. 12. 29.&gt;<br> ② 계정과목의 명칭은 일반적으로 적용되는 회계원칙에 따라 재단의 회계에 부합할 수 있는 과목으로 정할 수 있다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (회계장부) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (회계장부) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(회계장부)</strong> ① 회계부서에서는 다음의 회계장부를 갖추어 계정을 구분, 정리한다.</p><ol><li>분개장 (전표 및 일계표)</li><li>총계정원장</li><li>보조부 (각 계정의 보조장부, 현금출납부)</li><li>기타 필요한 장부<br> ② 각종 장표 및 증빙서류의 서식은 내규로 정한다.<br> ③ 제1항의 장부에 대하여 필요한 경우 컴퓨터 파일이나 그 출력의 유인물로 대체기장 및 보관할 수 있다.</li></ol><h2 id="article10" class="sr-only" tabindex="-1">제10조 (장부잔액의 확인) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (장부잔액의 확인) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(장부잔액의 확인)</strong> 원장과 각 관계 장부에 대하여 분임회계책임자 및 출납담당자는 항상 그 잔액을 검토하여 상호간에 정확히 일치하도록 확인하여야 한다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (개서 및 정정) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (개서 및 정정) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(개서 및 정정)</strong> ① 회계에 관한 서류에 개서 또는 정정하고자 할 때에는 당해 자구 및 숫자에 평행 붉은 선 2선을 긋고 정정자의 날인과 함께 정정하여야 하며 이 이외의 어떠한 방법의 개서 또는 정정도 인정되지 아니한다.<br> ② 제1항의 경우 횡서는 실선의 상부에 종서는 실선의 좌측에 정정 자구 또는 숫자를 기입한다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (기장전표의 정정) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (기장전표의 정정) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(기장전표의 정정)</strong> 기장전표의 정정은 새로운 대체전표의 발급에 의하여야 하며 기장전표 그 자체를 정정하여서는 아니 된다.</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (일계표) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (일계표) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(일계표)</strong> 일계표는 계정과목 집계표에 의하여 작성하며, 매월 초 전월 월계표를 분임회계책임자에게 보고하여야 한다. 단, 전산회계프로그램을 이용하는 경우 전산자료로 보고 할 수 있다. &lt;개정 2014. 3. 31.&gt;</p><h2 id="제3장-수입과-지출" tabindex="-1">제3장 수입과 지출 <a class="header-anchor" href="#제3장-수입과-지출" aria-label="Permalink to &quot;제3장 수입과 지출&quot;">​</a></h2><h2 id="article14" class="sr-only" tabindex="-1">제14조 (금전의 범위) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (금전의 범위) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(금전의 범위)</strong> ① 금전은 현금, 예금, 수표, 우편환증서를 말한다.<br> ② 당일로 현금화할 수 있는 어음과 기타 유가증권 등 제증서도 금전에 준하여 취급한다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (수입) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (수입) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(수입)</strong> 회계책임자는 수입을 총괄하고, 분임회계책임자는 수입을 관리하며, 분임회계원은 소관 사업수입의 징수ㆍ납부를 관리한다.</p><h2 id="article16" class="sr-only" tabindex="-1">제16조 (수납과 징수의 원칙) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (수납과 징수의 원칙) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(수납과 징수의 원칙)</strong> 수납과 징수는 규정, 계약 등에서 정하는 바에 따라 회계결의서에 의하되 관계 증빙서를 첨부하여야 한다.</p><h2 id="article17" class="sr-only" tabindex="-1">제17조 (반납금 수입과 여입) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (반납금 수입과 여입) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(반납금 수입과 여입)</strong> ① 출납이 발생한 연도에 속하는 수입 기타 예산외의 수입은 모두 당해연도의 수입에 납입하여야 한다.<br> ② 사업비의 잔액 등 반납금은 당해 년도에 그 지급한 과목에 여입 하여야 한다.</p><h2 id="article18" class="sr-only" tabindex="-1">제18조 (지급) <a class="header-anchor" href="#article18" aria-label="Permalink to &quot;제18조 (지급) {#article18 .sr-only}&quot;">​</a></h2><p><strong>제18조(지급)</strong> ① 지급은 회계결의서에 의하여 예산배정액과 예금 잔고를 초과하지 않는 범위 내에서 행하여야 한다.<br> ② 지급의 순위는 채무의 발생순위에 따르되, 자금의 순환이 충족되지 못할 때에는 그 지급순위는 대표이사가 결정한다.<br> ③ 10만원 이상의 대가의 지급은 계좌에 입금함을 원칙으로 하며 계좌입금이 불가능할 경우에는 그러하지 아니하다. 다만, 전도금에 대하여는 소관부서에서 직접 집행한다.<br> ④ 당해 사업연도에 속하는 비용은 그 연도 중에 지급하여야 한다. 다만, 부득이한 사유로 인하여 그 연도 중에 지급하지 못한 분에 대하여는 미결산 계정을 통하여 익년도에 지급할 수 있다.<br> ⑤ 각 부서에서는 대금 지급과 관련된 증빙서류를 반드시 첨부하여야 한다.<br> ⑥ 증빙서류의 세부목록은 기업회계기준 및 세법에 규정된 객관적 자료를 말하며 분임회계책임자는 그 외의 필요한 자료를 요구 할 수 있다.</p><h2 id="article19" class="sr-only" tabindex="-1">제19조 (출납담당자) <a class="header-anchor" href="#article19" aria-label="Permalink to &quot;제19조 (출납담당자) {#article19 .sr-only}&quot;">​</a></h2><p><strong>제19조(출납담당자)</strong> 출납담당자는 특별히 정하여진 경우 및 분임회계책임자의 승인이 있을 경우를 제외하고는 전표를 발급하지 못하며 금전의 수납과 내역에 관한 기장업무 이외의 장부기장업무는 회계담당부서장의 지시가 없는 한 이에 임할 수 없다.</p><h2 id="article20" class="sr-only" tabindex="-1">제20조 (출납담당자의 책임과 의무) <a class="header-anchor" href="#article20" aria-label="Permalink to &quot;제20조 (출납담당자의 책임과 의무) {#article20 .sr-only}&quot;">​</a></h2><p><strong>제20조(출납담당자의 책임과 의무)</strong> ① 현금의 출납은 출납담당자만이 이를 취급할 수 있다.<br> ② 출납담당자는 출납의 정확을 기하여야 하며 취급하는 금전 및 유가증권에 대하여 보관의 책임을 부담하고 손망실 등의 사고가 발생하였을 때에는 지체 없이 대표이사에게 보고하여야 하며, 재해ㆍ도난ㆍ기타 불가항력에 의한 사고일 경우에는 변상의 책임을 지진 않지만 이사회를 통한 책임해제의 결정은 받아야 한다.</p><h2 id="article21" class="sr-only" tabindex="-1">제21조 (전도금) <a class="header-anchor" href="#article21" aria-label="Permalink to &quot;제21조 (전도금) {#article21 .sr-only}&quot;">​</a></h2><p><strong>제21조(전도금)</strong> ① 다음 각호의 업무는 현금으로 전도할 수 있다.</p><ol><li>외국에서 지급하는 경비</li><li>기밀비, 업무추진비</li><li>재단 상용의 경비와 여비로서 500만원 한도안의 경비로서 제세공과금 및 소모품의 매입, 제조ㆍ운반 등의 경우에는 1건당 금액이 100만원 이내</li><li>재단 업무와 관련하여 소속 직원이외의 일반인에게 지급하는 여비 및 기타경비</li><li>기타 대표이사의 승인을 받는 경우<br> ② 전도금을 지급받은 자는 시행내규에 따라 관련 업무가 완료되면 지체 없이 전도금을 정산하여야 한다.<br> ③ 정산증빙서류는 자금요청서에 명시된 사용목적의 내용과 거래 사실이 입증될 수 있는 것이어야 한다.</li></ol><h2 id="article22" class="sr-only" tabindex="-1">제22조 (선급금) <a class="header-anchor" href="#article22" aria-label="Permalink to &quot;제22조 (선급금) {#article22 .sr-only}&quot;">​</a></h2><p><strong>제22조(선급금)</strong> 반대급부 또는 행위가 완료되기 이전에 자금을 지급하지 아니하면 업무나 사업에 지장을 초래할 우려가 있는 다음 각호의 성질의 비용에 대하여는 그 금액의 전부 또는 일부를 선급할 수 있다.</p><ol><li>외국에서 직접 구입하는 물품, 도서, 기자재의 대가</li><li>정기간행물의 대가</li><li>토지 또는 건물의 임차료</li><li>운임</li><li>공사, 제조 또는 용역 계약금액의 대가로서 계약금액의 100분의 70을 초과하지 아니하는 금액 &lt;개정 2014. 3. 31., 2016. 3. 29.&gt;</li><li>공공기관 또는 관련 기관에 대하여 지급하는 경비</li><li>위탁비, 사례비</li><li>재단이 초청한 외국인에게 국내에서 지급하는 경비</li><li>기타 대표이사가 승인하는 경비</li></ol><h2 id="article23" class="sr-only" tabindex="-1">제23조 (금전의 수납) <a class="header-anchor" href="#article23" aria-label="Permalink to &quot;제23조 (금전의 수납) {#article23 .sr-only}&quot;">​</a></h2><p><strong>제23조(금전의 수납)</strong> ① 현금의 수납은 회계결의서와 기타 증빙서류에 의한다.<br> ② 수표 및 어음에 의한 수납의 경우도 제1항의 규정에 준한다.<br> ③ 특별한 사유가 없는 한 수납한 현금은 원칙적으로 당일 중 은행에 입금 처리한다.<br> ④ 지급준비를 위하여 보관하는 소액의 현금과 유가증권은 분임회계책임자의 책임 하에 보관한다.</p><h2 id="article24" class="sr-only" tabindex="-1">제24조 (영수증의 발행) <a class="header-anchor" href="#article24" aria-label="Permalink to &quot;제24조 (영수증의 발행) {#article24 .sr-only}&quot;">​</a></h2><p><strong>제24조(영수증의 발행)</strong> ① 분임회계원이 금전을 수납한 경우에는 소정양식의 세금계산서, 또는 입금표를 작성, 교부하여야 한다. 다만, 재단 내 관련 영수증은 분임회계책임자의 확인 인이 있는 회계결의서로서 이를 대신할 수 있다.<br> ② 상대방의 금전이 수납 이전에 영수증의 발행을 요구하는 경우에는 영수증발행의뢰서를 제출 받아야 한다.</p><h2 id="article25" class="sr-only" tabindex="-1">제25조 (지출원인행위) <a class="header-anchor" href="#article25" aria-label="Permalink to &quot;제25조 (지출원인행위) {#article25 .sr-only}&quot;">​</a></h2><p><strong>제25조(지출원인행위)</strong> 지출원인행위를 하고자 할 때에는 지출품의서 또는 회계결의서를 작성하여야 한다.</p><h2 id="article26" class="sr-only" tabindex="-1">제26조 (영수증의 징수) <a class="header-anchor" href="#article26" aria-label="Permalink to &quot;제26조 (영수증의 징수) {#article26 .sr-only}&quot;">​</a></h2><p><strong>제26조(영수증의 징수)</strong> 금전을 지급할 때에는 반드시 정당한 수취인의 영수증 또는 이에 갈음하는 증서를 징수하고 회계결의서에 첨부하여야 한다.</p><h2 id="article27" class="sr-only" tabindex="-1">제27조 (송금지급) <a class="header-anchor" href="#article27" aria-label="Permalink to &quot;제27조 (송금지급) {#article27 .sr-only}&quot;">​</a></h2><p><strong>제27조(송금지급)</strong> 송금지급을 할 경우에는 은행계좌입금 등 통상의 송금방법에 의한다.</p><h2 id="article28" class="sr-only" tabindex="-1">제28조 (재원) <a class="header-anchor" href="#article28" aria-label="Permalink to &quot;제28조 (재원) {#article28 .sr-only}&quot;">​</a></h2><p><strong>제28조(재원)</strong> ① 재단의 운영재원은 서울특별시와 정부, 기타 기관 등의 출연금, 기금에서 생긴 과실, 사업수익 및 기타 수입으로 한다.<br> ② 부득이한 사유로 차입금의 필요가 발생한 경우에는 대표이사가 승인을 얻어 차입할 수 있다. 다만, 장기차입에 대하여는 이사회의 승인을 얻어야 한다.</p><h2 id="article29" class="sr-only" tabindex="-1">제29조 (자금계획표) <a class="header-anchor" href="#article29" aria-label="Permalink to &quot;제29조 (자금계획표) {#article29 .sr-only}&quot;">​</a></h2><p><strong>제29조(자금계획표)</strong> 자금운용을 원활히 하기 위하여 지급예정과 수입예정, 그리고 시재액을 나타내는 자금계획표를 작성하여야 한다.</p><h2 id="article30" class="sr-only" tabindex="-1">제30조 (금전의 확인) <a class="header-anchor" href="#article30" aria-label="Permalink to &quot;제30조 (금전의 확인) {#article30 .sr-only}&quot;">​</a></h2><p><strong>제30조(금전의 확인)</strong> ① 분임회계책임자는 매일 출납시간 종료 후에 현금 잔액을 관계장부와 대조하여 일치하도록 하여야 한다.<br> ② 예금은 매월 말에 예금잔액을 은행장부와 대조하고 매 반기말 및 기말에는 은행의 예금잔액증명을 발급받아 그 잔액을 확인한다.</p><h2 id="article31" class="sr-only" tabindex="-1">제31조 (거래은행의 신설, 변경) <a class="header-anchor" href="#article31" aria-label="Permalink to &quot;제31조 (거래은행의 신설, 변경) {#article31 .sr-only}&quot;">​</a></h2><p><strong>제31조(거래은행의 신설, 변경)</strong> ① 거래은행의 신설, 변경 또는 취소에 대하여는 대표이사의 승인을 받아야 한다.<br> ② 수표, 어음행위, 차입금, 예금 및 환거래 등은 대표이사 명의로 행하여야 한다.<br> ③ 제2항에 있어서 대표이사가 특정한 자에게 위임할 경우에는 수임자의 명의로써 이를 대행 할 수 있다.</p><h2 id="article32" class="sr-only" tabindex="-1">제32조 (현금의 과부족) <a class="header-anchor" href="#article32" aria-label="Permalink to &quot;제32조 (현금의 과부족) {#article32 .sr-only}&quot;">​</a></h2><p><strong>제32조(현금의 과부족)</strong> 현금에 과부족이 발생한 때에는 출납담당자는 지체 없이 보고하여 분임회계책임자의 지시를 받아 그 원인을 규명한 후 바르게 처리하여야 한다.</p><h2 id="article33" class="sr-only" tabindex="-1">제33조 (규정외의 조치) <a class="header-anchor" href="#article33" aria-label="Permalink to &quot;제33조 (규정외의 조치) {#article33 .sr-only}&quot;">​</a></h2><p><strong>제33조(규정외의 조치)</strong> 이 규정 이외의 금전출납상의 조치에 대하여는 대표이사의 승인을 받아 이를 시행한다.</p><h2 id="제4장-자산-회계" tabindex="-1">제4장 자산 회계 <a class="header-anchor" href="#제4장-자산-회계" aria-label="Permalink to &quot;제4장 자산 회계&quot;">​</a></h2><p>제1절 총 칙</p><h2 id="article34" class="sr-only" tabindex="-1">제34조 (자산의 구분) <a class="header-anchor" href="#article34" aria-label="Permalink to &quot;제34조 (자산의 구분) {#article34 .sr-only}&quot;">​</a></h2><p><strong>제34조(자산의 구분)</strong> 자산은 업무용자산과 비업무용자산으로 구분하여 관리하여야 한다.</p><h2 id="article35" class="sr-only" tabindex="-1">제35조 (취득일) <a class="header-anchor" href="#article35" aria-label="Permalink to &quot;제35조 (취득일) {#article35 .sr-only}&quot;">​</a></h2><p><strong>제35조(취득일)</strong> ① 고정자산의 취득일은 취득계약서상의 잔금청산일로 한다. 다만, 실제 사용일, 잔금지급일 및 소유권 이전등기를 한 경우의 등기접수일이 취득계약서상의 잔금청산일보다 빠른 경우 이를 고정자산의 취득일로 한다.<br> ② 취득이 결정되었으나 사용이 불가능한 상태에 있는 경우 미착 재고자산으로 처리한다.</p><h2 id="article36" class="sr-only" tabindex="-1">제36조 (관리대장) <a class="header-anchor" href="#article36" aria-label="Permalink to &quot;제36조 (관리대장) {#article36 .sr-only}&quot;">​</a></h2><p><strong>제36조(관리대장)</strong> 자산의 관리를 위하여 자산별 대장을 비치하고 취득, 처분, 교환 등의 내용을 발생순으로 기장 정리하여야 한다.</p><p>제2절 유동 자산</p><h2 id="article37" class="sr-only" tabindex="-1">제37조 (채권에 대한 대손충당금) <a class="header-anchor" href="#article37" aria-label="Permalink to &quot;제37조 (채권에 대한 대손충당금) {#article37 .sr-only}&quot;">​</a></h2><p><strong>제37조(채권에 대한 대손충당금)</strong> 외상매출금ㆍ미수금ㆍ미수수익과 이와 유사한 채권에 대한 대손추산액을 산정함에 있어 채무자가 국가, 지방자치단체 또는 다른 국가 및 지방자치단체 투자기관인 경우에는 대손충당금 설정대상에서 이를 제외한다.</p><h2 id="article38" class="sr-only" tabindex="-1">제38조 (재고자산의 정리) <a class="header-anchor" href="#article38" aria-label="Permalink to &quot;제38조 (재고자산의 정리) {#article38 .sr-only}&quot;">​</a></h2><p><strong>제38조(재고자산의 정리)</strong> ① 재고자산은 적정수준을 정하여 관리의 합리화를 기하여야 한다.<br> ② 재고자산의 출납은 입ㆍ출고 전표에 의한다.<br> ③ 재고자산의 입고 및 출고에 관한 기록은 특별한 경우를 제외하고는 계속기록법에 의한다.</p><h2 id="article39" class="sr-only" tabindex="-1">제39조 (자연감모) <a class="header-anchor" href="#article39" aria-label="Permalink to &quot;제39조 (자연감모) {#article39 .sr-only}&quot;">​</a></h2><p><strong>제39조(자연감모)</strong> ① 물품의 장기보관이나 운송 기타 불가피한 사유로 인하여 생기는 감모는 자연감모로 정리할 수 있다.<br> ② 자연감모로 정리할 수 있는 재고자산의 종류, 품명 및 자연감모의 율에 관하여는 내규로 정한다.</p><p>제3절 고정자산</p><h2 id="article40" class="sr-only" tabindex="-1">제40조 (고정자산의 분류) <a class="header-anchor" href="#article40" aria-label="Permalink to &quot;제40조 (고정자산의 분류) {#article40 .sr-only}&quot;">​</a></h2><p><strong>제40조(고정자산의 분류)</strong> 유형자산, 무형자산, 투자자산으로 분류하고 관리할 범위는 기업회계기준에 의한다.</p><h2 id="article41" class="sr-only" tabindex="-1">제41조 (투자부동산의 주석) <a class="header-anchor" href="#article41" aria-label="Permalink to &quot;제41조 (투자부동산의 주석) {#article41 .sr-only}&quot;">​</a></h2><p><strong>제41조(투자부동산의 주석)</strong> 투자의 목적으로 또는 비업무용 등으로 소유하는 토지, 건물 및 기타의 부동산에 대하여는 주석으로 기재한다.</p><p>제4절 자산관리</p><h2 id="article42" class="sr-only" tabindex="-1">제42조 (건설 중인 자산) <a class="header-anchor" href="#article42" aria-label="Permalink to &quot;제42조 (건설 중인 자산) {#article42 .sr-only}&quot;">​</a></h2><p><strong>제42조(건설 중인 자산)</strong> ① 고정자산의 취득이 건설공사에 의한 경우에는 건설 중인 자산으로 정리하고, 그 취득을 완료할 때에는 당해 고정자산계정에 대체한다.<br> ② 제1항의 건설 중인 자산에는 건설기간 중 건설자금에 대하여 발생한 금융비용을 포함한다.</p><h2 id="article43" class="sr-only" tabindex="-1">제43조 (유형자산의 처분결정) <a class="header-anchor" href="#article43" aria-label="Permalink to &quot;제43조 (유형자산의 처분결정) {#article43 .sr-only}&quot;">​</a></h2><p><strong>제43조(유형자산의 처분결정)</strong> 유형자산을 처분하고자 할 때에는 유형자산에 대하여 불용결정을 하여야 한다.</p><h2 id="article44" class="sr-only" tabindex="-1">제44조 (담보제공) <a class="header-anchor" href="#article44" aria-label="Permalink to &quot;제44조 (담보제공) {#article44 .sr-only}&quot;">​</a></h2><p><strong>제44조(담보제공)</strong> 고정자산을 담보로 제공하고자 할 때에는 이사회의 의결을 얻어야 한다.</p><h2 id="article45" class="sr-only" tabindex="-1">제45조 (감가상각의 범위) <a class="header-anchor" href="#article45" aria-label="Permalink to &quot;제45조 (감가상각의 범위) {#article45 .sr-only}&quot;">​</a></h2><p><strong>제45조(감가상각의 범위)</strong> 고정자산은 다음 각호의 요령에 의하여 감가상각을 하여야 한다. 다만, 비상각자산 및 매도계약을 체결한 고정자산은 그러하지 아니한다.</p><ol><li>고정자산은 토지, 입목 및 건설 중에 있는 것을 제외하고는 연도마다 감가상각을 하여야 하며 취득년도부터 개시한다.</li><li>감가상각자산의 노후화로 인한 현저한 가치감소와 기타 경영상 특히 필요한 경우에는 특별상각 또는 이연상각을 할 수 있다.</li><li>감가상각방법은 법인세법에서 정한 정액법에 의한다.</li><li>감가상각의 기장처리는 유형고정자산은 간접법에 의하고 무형고정자산은 직접법에 의한다.</li></ol><h2 id="article46" class="sr-only" tabindex="-1">제46조 (법인세법 준용) <a class="header-anchor" href="#article46" aria-label="Permalink to &quot;제46조 (법인세법 준용) {#article46 .sr-only}&quot;">​</a></h2><p><strong>제46조(법인세법 준용)</strong> 고정자산의 내용연수, 상각률 기타 감가상각에 필요한 사항은 법인세법이 정한 바에 의한다. 다만, 법인세법에 정하는 바가 없거나 동법에 의하기 곤란한 경우에는 대표이사의 승인을 받아 시행하여야 한다.</p><h2 id="제5장-부채-및-자본회계" tabindex="-1">제5장 부채 및 자본회계 <a class="header-anchor" href="#제5장-부채-및-자본회계" aria-label="Permalink to &quot;제5장 부채 및 자본회계&quot;">​</a></h2><h2 id="article47" class="sr-only" tabindex="-1">제47조 (부채의 구분) <a class="header-anchor" href="#article47" aria-label="Permalink to &quot;제47조 (부채의 구분) {#article47 .sr-only}&quot;">​</a></h2><p><strong>제47조(부채의 구분)</strong> 부채는 유동부채와 고정부채로 구분한다.</p><h2 id="article48" class="sr-only" tabindex="-1">제48조 (자본의 구분) <a class="header-anchor" href="#article48" aria-label="Permalink to &quot;제48조 (자본의 구분) {#article48 .sr-only}&quot;">​</a></h2><p><strong>제48조(자본의 구분)</strong> 자본은 자본금, 잉여금 및 자본조정계정으로 한다.</p><h2 id="article49" class="sr-only" tabindex="-1">제49조 (자본금의 구분) <a class="header-anchor" href="#article49" aria-label="Permalink to &quot;제49조 (자본금의 구분) {#article49 .sr-only}&quot;">​</a></h2><p><strong>제49조(자본금의 구분)</strong> 자본금은 다음 각호와 같이 구분한다.</p><ol><li>설립당시 기본으로 출연한 재산</li><li>설립 후 정부, 지방자치단체, 기타 법인 및 개인의 출연금 또는 토지ㆍ건물 등의 부동산</li><li>기금으로 적립한 금액</li><li>정부 및 지방자치단체의 보조금과 결산상 잉여금 중 이사회에서 기본재산으로 편입하도록 의결한 재산</li><li>기타의 재산</li></ol><h2 id="제6장-손익-계산" tabindex="-1">제6장 손익 계산 <a class="header-anchor" href="#제6장-손익-계산" aria-label="Permalink to &quot;제6장 손익 계산&quot;">​</a></h2><h2 id="article50" class="sr-only" tabindex="-1">제50조 (계산의 원칙) <a class="header-anchor" href="#article50" aria-label="Permalink to &quot;제50조 (계산의 원칙) {#article50 .sr-only}&quot;">​</a></h2><p><strong>제50조(계산의 원칙)</strong> ① 제 수익과 비용은 발생의 사실에 따라 총액에 의하여 계산하고 수익을 비용과 직접 상계하거나 운영성과표에서 제외하여서는 아니 된다. &lt;개정 2021. 12. 29.&gt;<br> ② 수익의 발생은 실현시기에 의함을 원칙으로 한다.<br> ③ 수익과 비용은 그 발생원천에 따라 분류하고 각 수익항목과 그에 관련되는 비용항목을 대조 표시하여야 한다.<br> ④ 이외의 일반적 계산은 기업회계기준에서 정하는 바에 따른다.</p><h2 id="article51" class="sr-only" tabindex="-1">제51조 (매출액ㆍ매출원가) <a class="header-anchor" href="#article51" aria-label="Permalink to &quot;제51조 (매출액ㆍ매출원가) {#article51 .sr-only}&quot;">​</a></h2><p><strong>제51조(매출액ㆍ매출원가)</strong> 매출액ㆍ매출원가 등의 기재에 대하여는 기업회계기준에 따른다.</p><h2 id="article52" class="sr-only" tabindex="-1">제52조 (정부보조금 등) <a class="header-anchor" href="#article52" aria-label="Permalink to &quot;제52조 (정부보조금 등) {#article52 .sr-only}&quot;">​</a></h2><p><strong>제52조(정부보조금 등)</strong> 정부보조금 등의 처리는 기업회계기준에 따른다.</p><h2 id="제7장-결-산" tabindex="-1">제7장 결 산 <a class="header-anchor" href="#제7장-결-산" aria-label="Permalink to &quot;제7장 결 산&quot;">​</a></h2><h2 id="article53" class="sr-only" tabindex="-1">제53조 (결산) <a class="header-anchor" href="#article53" aria-label="Permalink to &quot;제53조 (결산) {#article53 .sr-only}&quot;">​</a></h2><p><strong>제53조(결산)</strong> 결산은 회계기간의 경영성과와 재무상태를 명확하게 표시할 수 있도록 하여야 한다.</p><h2 id="article54" class="sr-only" tabindex="-1">제54조 (결산승인) <a class="header-anchor" href="#article54" aria-label="Permalink to &quot;제54조 (결산승인) {#article54 .sr-only}&quot;">​</a></h2><p><strong>제54조(결산승인)</strong> ① 대표이사는 회계연도 종료 후 2개월 이내에 결산을 완료하고 10일 이내에 사업실적 및 결산 보고서를 작성하여 이사회의 승인을 얻어야 하며, 다음 각 호의 서류를 첨부하여 시장과 주무관청에 제출하고 시장의 승인을 받아야 한다. &lt;개정 2014. 3. 31., 2021. 12. 29.&gt;</p><ol><li>예산, 재무결산보고서 및 부속명세서</li><li>당해 사업연도의 사업보고서</li><li>회계감사인의 회계감사보고서<br> ② &lt;개정 2014. 3. 31.&gt;, 삭제 &lt;2021. 12. 29.&gt;</li></ol><h2 id="article55" class="sr-only" tabindex="-1">제55조 (불확정채권, 채무의 정리) <a class="header-anchor" href="#article55" aria-label="Permalink to &quot;제55조 (불확정채권, 채무의 정리) {#article55 .sr-only}&quot;">​</a></h2><p><strong>제55조(불확정채권, 채무의 정리)</strong> 불확정채권, 채무의 정리에 대하여는 기업회계기준에 의한다.</p><h2 id="article56" class="sr-only" tabindex="-1">제56조 (결손처리) <a class="header-anchor" href="#article56" aria-label="Permalink to &quot;제56조 (결손처리) {#article56 .sr-only}&quot;">​</a></h2><p><strong>제56조(결손처리)</strong> 결산정리에 따라 결손처리 하여야 할 사항이 발생하는 경우에는 그 성질에 따라 영업외비용 또는 특별손실로 계상한다.</p><h2 id="article57" class="sr-only" tabindex="-1">제57조 (잉여금의 처리) <a class="header-anchor" href="#article57" aria-label="Permalink to &quot;제57조 (잉여금의 처리) {#article57 .sr-only}&quot;">​</a></h2><p><strong>제57조(잉여금의 처리)</strong> 매 회계연도의 세입ㆍ세출결산 잉여금은 이사회의 의결을 거친 후 다음연도에 이월하여 목적 사업에 전입 사용하거나 기본재산에 편입한다.</p><h2 id="article58" class="sr-only" tabindex="-1">제58조 (결손금의 처리) <a class="header-anchor" href="#article58" aria-label="Permalink to &quot;제58조 (결손금의 처리) {#article58 .sr-only}&quot;">​</a></h2><p><strong>제58조(결손금의 처리)</strong> 결손금의 처리를 다음 순으로 보전한다. 다만, 관계법령으로 따로 규정된 경우에는 그러하지 아니하다.</p><ol><li>임의적립금이입액</li><li>이익준비금이입액</li><li>자본잉여금이입액</li></ol><h2 id="제8장-계-약" tabindex="-1">제8장 계 약 <a class="header-anchor" href="#제8장-계-약" aria-label="Permalink to &quot;제8장 계 약&quot;">​</a></h2><p>제1절 총 칙</p><h2 id="article59" class="sr-only" tabindex="-1">제59조 (계약원칙) <a class="header-anchor" href="#article59" aria-label="Permalink to &quot;제59조 (계약원칙) {#article59 .sr-only}&quot;">​</a></h2><p><strong>제59조(계약원칙)</strong> ① 계약은 재단에 가장 유익한 효과를 가져 올 수 있다고 기대되는 방법으로 체결함을 원칙으로 한다.<br> ② 계약은 일반경쟁입찰에 의함을 원칙으로 하되 대표이사가 필요하다고 인정할 경우에는 지명경쟁입찰, 제한경쟁입찰, 수의계약 등에 의할 수 있다.<br> ③ 재단설립목적 범위내의 수익사업과 관련한 제 계약은 대표이사가 정하는 바에 따른다.<br> ④ 발주담당자는 부당한 계약을 방지하기 위하여 별표 1의 부당계약 조건이 포함되지 않도록 하여야 하며, 별표 1의 항목은 발주담당자가 1차 점검을 하고, 계약담당자 2차 점검을 하여야 한다. &lt;신설 2016. 10. 7.&gt;<br> ⑤ 이 규정 및 다른 법령에 특별한 규정이 있는 경우를 제외하고는 지방자치단체를 당사자로 하는 계약에 관한 법률을 준용한다. &lt;개정 2008. 3. 28.&gt;</p><h2 id="article60" class="sr-only" tabindex="-1">제60조 (계약서의 작성) <a class="header-anchor" href="#article60" aria-label="Permalink to &quot;제60조 (계약서의 작성) {#article60 .sr-only}&quot;">​</a></h2><p><strong>제60조(계약서의 작성)</strong> ① 계약을 하고자 할 때에는 계약의 목적과 금액, 이행기간, 보증금액, 계약위반 시 보증금의 처리, 지급방법, 위험부담, 지체상금, 기타 필요한 사항을 상세히 기재한 계약서를 작성한다.<br> ② 제1항의 계약서는 대표이사명의로 작성되어야 한다. 다만, 대표이사가 계약체결에 관한 권한을 위임하였을 때에는 그 위임 받은 자가 이를 대행할 수 있다.</p><h2 id="article61" class="sr-only" tabindex="-1">제61조 (계약서의 작성생략) <a class="header-anchor" href="#article61" aria-label="Permalink to &quot;제61조 (계약서의 작성생략) {#article61 .sr-only}&quot;">​</a></h2><p><strong>제61조(계약서의 작성생략)</strong> 다음 각호의 경우에는 계약서를 생략할 수 있다. 다만, 청구서, 각서, 협정서, 승낙사항 등 계약 성립의 근거가 될 수 있는 서류를 받아 비치하여야 한다.</p><ol><li>계약금액이 5천만원 이하인 계약을 체결할 때 &lt;개정 2014. 12. 29.&gt;</li><li>물품매각의 경우에 있어서는 매수인이 즉시 대금을 납부하고 그 물품을 인수할 때</li><li>관영 관허요금 또는 요율에 의하여 계약을 할 때</li><li>정부투자기관 및 서울특별시의 투자기관 또는 자본금의 5할 이상을 정부나 지방자치 단체가 투자한 법인과 계약을 할 때</li></ol><h2 id="article62" class="sr-only" tabindex="-1">제62조 (계약보증금) <a class="header-anchor" href="#article62" aria-label="Permalink to &quot;제62조 (계약보증금) {#article62 .sr-only}&quot;">​</a></h2><p><strong>제62조(계약보증금)</strong> 계약을 체결하고자 하는 자는(국가기관과 지방자치단체 및 공공단체는 제외) 현금, 국공채 또는 이행보증보험증서, 건설공제조합 등이 발행하는 보증서로서 계약금의 10/100이상의 보증금을 납부하여야 한다. 다만, 계약금액이 5천만원 이하인 계약을 체결하는 경우에는 보증금을 면제할 수 있으며, 재단이 필요하다고 인정하는 때에는 계약보증금에 해당하는 금액을 현금으로 납입할 것을 보증하기 위한 계약보증지급각서를 제출케 할 수 있다. &lt;개정 2008. 3. 28., 2014. 12. 29.&gt;</p><h2 id="article63" class="sr-only" tabindex="-1">제63조 (계약의 방법) <a class="header-anchor" href="#article63" aria-label="Permalink to &quot;제63조 (계약의 방법) {#article63 .sr-only}&quot;">​</a></h2><p><strong>제63조(계약의 방법)</strong> 대표이사 또는 그 위임을 받은 자는 계약을 체결하고자 하는 경우에는 일간신문에 게재하거나 재단 또는 서울시홈페이지에 게시하는 방법 등으로 공고하여야 하며, 전기통신사업법에 의한 전기통신사업자의 통신망을 이용한 공고를 병행할 수 있다. 다만, 계약의 목적ㆍ성질ㆍ규모 등을 고려하여 필요하다고 인정될 때에는 참가자의 자격을 제한하거나 참가자를 지명하여 경쟁에 부치거나 수의계약에 의할 수 있다.</p><p>제2절 추정가격 및 예정가격</p><h2 id="article64" class="sr-only" tabindex="-1">제64조 (추정가격의 산정) <a class="header-anchor" href="#article64" aria-label="Permalink to &quot;제64조 (추정가격의 산정) {#article64 .sr-only}&quot;">​</a></h2><p><strong>제64조(추정가격의 산정)</strong> 대표이사 또는 그 위임을 받은 자는 예산에 계상된 금액 등을 기준으로 하여 추정가격을 산정한다.</p><h2 id="article65" class="sr-only" tabindex="-1">제65조 (예정가격의 비치) <a class="header-anchor" href="#article65" aria-label="Permalink to &quot;제65조 (예정가격의 비치) {#article65 .sr-only}&quot;">​</a></h2><p><strong>제65조(예정가격의 비치)</strong> ① 대표이사 또는 그 위임을 받은 자는 경쟁입찰 또는 수의계약에 부칠 사항에 대하여 당해 규격서 및 설계서등에 의하여 예정가격을 결정하고 이를 봉하여 미리 개찰장소 또는 가격협상 장소 등에 두어야 하며, 예정가격이 누설되지 않도록 하여야 한다. 다만, 공개가 불가피하다고 인정할 경우에는 예정가격을 공개하여 입찰에 부칠 수 있다.<br> ② 대표이사 또는 그 위임을 받은 자는 수의계약 및 개산계약, 협상에 의한 계약을 체결하고자 할 때에는 예정가격을 작성하지 아니할 수 있으며, 일괄입찰 및 실시설계ㆍ시공입찰에 있어서는 예정가격을 작성하지 아니한다. &lt;개정 2014. 12. 29.&gt;</p><h2 id="article66" class="sr-only" tabindex="-1">제66조 (예정가격의 결정방법) <a class="header-anchor" href="#article66" aria-label="Permalink to &quot;제66조 (예정가격의 결정방법) {#article66 .sr-only}&quot;">​</a></h2><p><strong>제66조(예정가격의 결정방법)</strong> 예정가격은 계약하고자 하는 사항의 가격의 총액에 대하여 정하여야 한다. 다만, 일정한 기간 계속하여야 하는 제조ㆍ공사ㆍ수리ㆍ가공ㆍ매매ㆍ공급ㆍ임차 등을 하는 계약의 경우에 있어서는 단가에 대하여 그 예정가격을 정할 수 있다.</p><h2 id="article67" class="sr-only" tabindex="-1">제67조 (예정가격의 변경) <a class="header-anchor" href="#article67" aria-label="Permalink to &quot;제67조 (예정가격의 변경) {#article67 .sr-only}&quot;">​</a></h2><p><strong>제67조(예정가격의 변경)</strong> 대표이사 또는 그 위임을 받은 자는 재공고입찰에 있어서도 입찰자 또는 낙찰자가 없는 경우로서 당초의 예정가격으로는 수의계약을 체결할 수 없는 경우에는 당초의 예정가격을 변경하여 새로운 절차에 의한 경쟁입찰에 부칠 수 있다.</p><p>제3절 계약의 방법</p><h2 id="article68" class="sr-only" tabindex="-1">제68조 (입찰방법) <a class="header-anchor" href="#article68" aria-label="Permalink to &quot;제68조 (입찰방법) {#article68 .sr-only}&quot;">​</a></h2><p><strong>제68조(입찰방법)</strong> ① 이 규정에 의한 경쟁은 입찰방법으로 한다.<br> ② 대표이사 또는 그 위임을 받은 자는 동산의 매각에 대하여 필요 하다고 인정할 경우에는 이 규정에 의한 입찰방법에 준하여 경매에 부칠 수 있다.</p><h2 id="article69" class="sr-only" tabindex="-1">제69조 (입찰의 성립) <a class="header-anchor" href="#article69" aria-label="Permalink to &quot;제69조 (입찰의 성립) {#article69 .sr-only}&quot;">​</a></h2><p><strong>제69조(입찰의 성립)</strong> 경쟁입찰은 2인 이상의 유효한 입찰로 성립한다.</p><h2 id="article70" class="sr-only" tabindex="-1">제70조 (입찰의 참가자격) <a class="header-anchor" href="#article70" aria-label="Permalink to &quot;제70조 (입찰의 참가자격) {#article70 .sr-only}&quot;">​</a></h2><p><strong>제70조(입찰의 참가자격)</strong> 대표이사 또는 그 위임을 받은 자는 다음 각 호의 요건을 갖춘 자에 한하여 경쟁입찰에 참가하게 하여야 한다.</p><ol><li>당해 입찰의 목적물의 제조, 공급에 필요한 시설 또는 점포를 소유 또는 임차하고 있는 자</li><li>다른 법령의 규정에 의하여 허가ㆍ인가ㆍ면허ㆍ등록ㆍ신고 등을 요하거나 자격요건을 갖추어야 할 경우에는 당해 허가ㆍ인가ㆍ면허ㆍ등록ㆍ신고 등을 받았거나 당해 자격요건에 적합한 자</li><li>부가가치세법 제8조의 규정에 의하여 당해 사업에 관한 사업자등록증을 교부받은 자 &lt;개정 2014. 12. 29.&gt;</li></ol><h2 id="article71" class="sr-only" tabindex="-1">제71조 (재입찰 및 재공고입찰) <a class="header-anchor" href="#article71" aria-label="Permalink to &quot;제71조 (재입찰 및 재공고입찰) {#article71 .sr-only}&quot;">​</a></h2><p><strong>제71조(재입찰 및 재공고입찰)</strong> ① 경쟁입찰에 있어서 2인 이상의 유효한 입찰자가 없거나 낙찰자가 없는 경우 같은 장소에서 재입찰에 부칠 수 있다. 이 경우 재입찰은 새로운 입찰로 보지 아니하며, 입찰자 또는 입찰회수의 제한을 받지 아니한다.<br> ② 입찰자나 낙찰자가 없는 경우 또는 낙찰자가 계약을 체결하지 아니하는 경우에는 재공고입찰에 부칠 수 있다.</p><h2 id="article72" class="sr-only" tabindex="-1">제72조 (지명입찰대상자의 지명) <a class="header-anchor" href="#article72" aria-label="Permalink to &quot;제72조 (지명입찰대상자의 지명) {#article72 .sr-only}&quot;">​</a></h2><p><strong>제72조(지명입찰대상자의 지명)</strong> 대표이사 또는 그 위임을 받은 자는 지명경쟁입찰에 부치고자 할 때에는 5인 이상의 입찰자를 지명하여 2인 이상의 입찰참가 신청이 있어야 한다. 다만, 지명대상자가 5인 미만인 때에는 대상자를 모두 지명하여야 한다. &lt;개정 2010. 9. 1.&gt;</p><h2 id="article73" class="sr-only" tabindex="-1">제73조 (수의계약 집행기준) <a class="header-anchor" href="#article73" aria-label="Permalink to &quot;제73조 (수의계약 집행기준) {#article73 .sr-only}&quot;">​</a></h2><p><strong>제73조(수의계약 집행기준)</strong> 대표이사 또는 그 위임을 받은 자는 다음 각호의 1에 해당하는 경우에는 수의계약에 의할 수 있다.</p><ol><li>계약의 목적ㆍ성질 등에 비추어 경쟁을 할 수 없는 경우</li><li>천재지변ㆍ긴급한 행사ㆍ비상재해 기타 이에 준하는 경우로서 경쟁에 붙일 여유가 없을 경우</li><li>계약의 목적을 비밀히 할 필요가 있을 경우</li><li>당해물품의 생산자 또는 소지자가 1인뿐인 경우로서 다른 물품을 제조하게 하거나 구매하여서는 사업목적을 달성할 수 없는 경우</li><li>「건설산업기본법」에 의한 종합공사의 경우 추정가격이 2억원(「건설산업기본법」에 의한 전문공사의 경우에는 1억원, 「전기공사업법」에 의한 전기공사, 「정보통신공사업법」에 의한 정보통신공사 또는 「소방시설공사업법」에 의한 소방시설공사, 그 밖에 공사 관련 법령에 의한 공사의 경우에는 8천만원) 이하인 공사, 추정가격(임차 또는 임대의 경우에는 연액 또는 총액기준)이 5천만원 이하인 물품의 제조·구매·용역계약 또는 그 밖의 계약의 경우 &lt;개정 2008. 3. 28., 2014. 12. 29.&gt;</li><li>삭제 &lt;2014. 12. 29.&gt;</li><li>국가, 지방자치단체, 다른 투자기관, 재단이 다른 법인의 발행주식총수 또는 출자총액의 100분의 50이상을 소유하거나 출자한 종속법인(다른 투자기관의 종속법인을 제외한다), 재단 및 다른 투자기관의 소유 또는 출자지분의 합계가 당해 회사의 발행 주식 총수 또는 출자총액의 100분의 50이상인 회사 또는 정부가 기본재산의 100분의 50이상을 출연한 법인과 계약하는 경우 및 특별법에 의하여 직접 설립된 법인이 그 법률에서 정한 사업을 영위함으로써 직접 생산하는 물품의 제조, 구매 및 용역계약을 하거나 이들에게 직접 물건을 매각 또는 임대할 경우</li><li>물품의 가공, 하역, 운송 또는 보관을 함에 있어 경쟁에 부치는 것이 불리하다고 인정할 경우</li><li>삭제 &lt;2014. 12. 29.&gt;</li><li>삭제 &lt;2008. 3. 28.&gt;</li><li>방위사업법에 의한 방산물자를 방위산업체로부터 제조, 구매하는 경우 &lt;개정 2014. 12. 29.&gt;</li><li>농어촌정비법에 의한 농공지구 입주공장(새마을공장을 포함한다)이 직접 생산하는 물품을 제조, 구매할 경우 &lt;개정 2014. 12. 29.&gt;</li><li>사회복지사업법에 의하여 설립된 법인이 직접 생산하는 물품을 제조, 구매할 경우</li><li>법령의 규정에 의하여 국가사업을 위탁, 대행할 수 있는 자와 당해사업에 대한 계약을 할 경우</li><li>국산화촉진을 위하여 대표이사가 지정하는 개발 설정품을 그 생산자로부터 개발완료 확인 후 2년 이내의 기간에 제조ㆍ구매하는 경우</li><li>삭제 &lt;2010. 9. 1.&gt;</li></ol><h2 id="article74" class="sr-only" tabindex="-1">제74조 (재공고입찰등과 수의계약) <a class="header-anchor" href="#article74" aria-label="Permalink to &quot;제74조 (재공고입찰등과 수의계약) {#article74 .sr-only}&quot;">​</a></h2><p><strong>제74조(재공고입찰등과 수의계약)</strong> 대표이사 또는 그 위임을 받은 자는 재공고입찰에 부친 경우로서, 입찰자 또는 낙찰자가 없을 때 또는 이 규정에 의하여 경쟁입찰을 실시하였으나 입찰자가 1인뿐인 경우로서 재공고입찰을 실시하더라도 입찰참가자격을 갖춘 자가 1인 밖에 없음이 명백하다고 인정될 때에는 수의계약에 의할 수 있다. 이 경우 보증금과 기한을 제외하고는 최초 경쟁입찰에 붙일 때 정한 가격 기타조건을 변경할 수 없다.</p><h2 id="article75" class="sr-only" tabindex="-1">제75조 (낙찰자가 계약을 체결하지 아니할 때의 수의계약) <a class="header-anchor" href="#article75" aria-label="Permalink to &quot;제75조 (낙찰자가 계약을 체결하지 아니할 때의 수의계약) {#article75 .sr-only}&quot;">​</a></h2><p><strong>제75조(낙찰자가 계약을 체결하지 아니할 때의 수의계약)</strong> 대표이사 또는 그 위임을 받은 자는 낙찰자가 계약을 체결하지 아니하거나 계약체결 후 소정의 기일 내에 계약의 이행에 착수하지 아니하거나, 계약이행에 착수한 후 계약상의 의무를 이행하지 아니하여 계약을 해제 또는 해지한 경우에 그 낙찰금액보다 불리하지 아니한 범위 안에서 다른 자와 수의계약을 할 수 있다. 다만, 기한을 제외하고는 최초의 입찰에 부칠 때 정한 가격 기타 조건을 변경할 수 없다.</p><h2 id="article76" class="sr-only" tabindex="-1">제76조 (견적에 의한 가격결정) <a class="header-anchor" href="#article76" aria-label="Permalink to &quot;제76조 (견적에 의한 가격결정) {#article76 .sr-only}&quot;">​</a></h2><p><strong>제76조(견적에 의한 가격결정)</strong> 대표이사 또는 그 위임을 받은 자는 수의계약을 체결하고자 할 경우에는 계약상대자에게 견적서를 제출하게 하여야 하며, 계약담당은 견적가격이 예정가격의 범위 안에 들지 아니하는 경우에는 다시 견적서를 제출하게 하여 가격을 결정하여야 한다. 다만, 전기ㆍ가스ㆍ수도 등의 공급계약 및 추정가격이 100만원 미만인 물품의 제조ㆍ구매ㆍ임차 및 용역계약에 있어서는 견적서 제출을 생략하게 할 수 있다. &lt;개정 2004. 4. 27.&gt;</p><p>제4절 입찰 및 낙찰절차</p><h2 id="article77" class="sr-only" tabindex="-1">제77조 (입찰공고) <a class="header-anchor" href="#article77" aria-label="Permalink to &quot;제77조 (입찰공고) {#article77 .sr-only}&quot;">​</a></h2><p><strong>제77조(입찰공고)</strong> ① 대표이사 또는 그 위임을 받은 자는 입찰방법에 의하여 경쟁에 부치고자 할 때에는 그 입찰서 제출마감일의 전일부터 기산하여 적어도 7일 전에 지정정보처리장치를 이용하여 공고하여야 한다. 다만, 필요한 경우 일간신문에 게재하거나 재단 또는 서울시홈페이지를 이용한 공고를 병행할 수 있다. &lt;개정 2008. 3. 28.&gt;<br> ②~④ &lt;생략 2008. 3. 28.&gt;</p><h2 id="article78" class="sr-only" tabindex="-1">제78조 (입찰참가신청) <a class="header-anchor" href="#article78" aria-label="Permalink to &quot;제78조 (입찰참가신청) {#article78 .sr-only}&quot;">​</a></h2><p><strong>제78조(입찰참가신청)</strong> ① 대표이사 또는 그 위임을 받은 자는 경쟁에 참가하고자 하는 자로 하여금 입찰일 전일까지 다음 각호의 서류를 제출하게 하여야 한다.</p><ol><li>입찰참가신청서</li><li>입찰참가 자격요건 증명서류</li><li>기타 입찰공고에서 요구한 서류<br> ② 제1항의 규정에 의한 입찰참가신청서류를 접수한 때에는 입찰 참가신청필증을 교부하여야 한다. 다만, 필요하지 아니하다고 인정할 때에는 그러하지 아니하다.</li></ol><h2 id="article79" class="sr-only" tabindex="-1">제79조 (입찰보증금) <a class="header-anchor" href="#article79" aria-label="Permalink to &quot;제79조 (입찰보증금) {#article79 .sr-only}&quot;">​</a></h2><p><strong>제79조(입찰보증금)</strong> ① 대표이사 또는 그 위임을 받은 자는 경쟁입찰에 참가하고자 하는 자로 하여금 입찰신청 마감일까지 입찰참가신청서와 함께 입찰보증금을 납부하게 하여야 한다.<br> ② 제1항의 규정에 의한 입찰보증금은 입찰금액의 100분의5로 하여야 하며, 입찰공고에 입찰보증금 납부 고지를 하여야 한다. 다만, 관계법령에 의하여 면허ㆍ인가ㆍ허가 등을 받고 당해 사업을 영위하고 있는 자로서 입찰 참가신청 시 소정의 보증금 지급 확약서를 제출한 자는 입찰보증금을 면제 할 수 있다. &lt;개정 2016. 10. 7.&gt;</p><h2 id="article80" class="sr-only" tabindex="-1">제80조 (입찰방법) <a class="header-anchor" href="#article80" aria-label="Permalink to &quot;제80조 (입찰방법) {#article80 .sr-only}&quot;">​</a></h2><p><strong>제80조(입찰방법)</strong> ① 대표이사 또는 그 위임을 받은 자는 경쟁입찰에 참가하고자 하는 자로 하여금 입찰서를 제출하게 하여야 한다. 이 경우 입찰서는 1인 1통이어야 한다.<br> ② 대표이사 또는 그 위임을 받은 자는 입찰에 참가하고자 하는 자의 위임을 받은 자가 입찰 전에 위임장을 제출한 때 또는 입찰참가대리인으로 등록을 한 자가 입찰참가증을 제시한 때에는 대리인을 당해 입찰에 참가하게 할 수 있다.<br> ③ 제1항 및 제2항 규정에 의하여 입찰서를 접수한 때에는 확인, 날인하고 개찰 시까지 개봉하지 아니하고 보관하여야 한다.<br> ④ 제1항의 규정에 의하여 제출되는 입찰서에 사용되는 인감은 입찰참가 신청을 한 때에 제출한 인감신고서의 인감(외국인의 경우 서명 가능)이어야 한다.</p><h2 id="article81" class="sr-only" tabindex="-1">제81조 (입찰서의 제출ㆍ접수) <a class="header-anchor" href="#article81" aria-label="Permalink to &quot;제81조 (입찰서의 제출ㆍ접수) {#article81 .sr-only}&quot;">​</a></h2><p><strong>제81조(입찰서의 제출ㆍ접수)</strong> 입찰서는 입찰공고에 표시한 장소와 일시에 입찰자가 직접 제출하는 것을 원칙으로 한다. 다만, 우편입찰 등이 허용된 경우에는 우편으로 제출하게 할 수 있다.</p><h2 id="article82" class="sr-only" tabindex="-1">제82조 (개찰 및 낙찰선언) <a class="header-anchor" href="#article82" aria-label="Permalink to &quot;제82조 (개찰 및 낙찰선언) {#article82 .sr-only}&quot;">​</a></h2><p><strong>제82조(개찰 및 낙찰선언)</strong> ① 개찰은 입찰공고에서 정한 장소와 일시에 입찰자가 출석한 자리에서 이를 행하여야 한다. 다만, 입찰자로서 개찰에 출석하지 아니한 자가 있을 때에는 입찰사무에 관계없는 직원으로 하여금 개찰에 입회하게 하여야 한다.<br> ② 대표이사 또는 그 위임을 받은 자는 입찰서를 지정된 시간까지 접수한 때에는 입찰서의 접수 마감을 선언하고 입찰자의 참석 하에 입찰서를 개봉하여야 한다.<br> ③ 대표이사 또는 그 위임을 받은 자는 개봉된 입찰서를 확인하고 유효한 입찰서의 입찰금액과 예정가격을 대조하여 지체 없이 적격자를 낙찰예정자 또는 낙찰자로 선정하여야 한다. 다만, 계약이행능력을 심사하여 낙찰자를 결정하는 등 낙찰자 결정에 장시간이 소요되는 경우에는 그러하지 아니한다.<br> ④ 대표이사 또는 그 위임을 받은 자는 낙찰이 될 동일조건의 입찰자가 2인 이상 있을 때에는 추첨에 의하여 결정한다.</p><p>제5절 계약의 이행</p><h2 id="article83" class="sr-only" tabindex="-1">제83조 (계약보증금의 귀속) <a class="header-anchor" href="#article83" aria-label="Permalink to &quot;제83조 (계약보증금의 귀속) {#article83 .sr-only}&quot;">​</a></h2><p><strong>제83조(계약보증금의 귀속)</strong> 대표이사 또는 그 위임을 받은 자는 계약 상대자가 정당한 이유 없이 계약상의 의무를 이행하지 아니한 때에는 당해 계약보증금을 재단에 귀속시켜야 한다. 이 경우 계약해제 및 해지 규정을 준용한다.</p><h2 id="article84" class="sr-only" tabindex="-1">제84조 (손해보험의 가입) <a class="header-anchor" href="#article84" aria-label="Permalink to &quot;제84조 (손해보험의 가입) {#article84 .sr-only}&quot;">​</a></h2><p><strong>제84조(손해보험의 가입)</strong> 대표이사 또는 그 위임을 받은 자는 계약을 체결함에 있어서 필요하다고 인정할 때에는 당해 계약의 목적물 등에 대하여 손해보험에 가입하거나, 계약 상대자로 하여금 손해보험에 가입하게 할 수 있다.</p><h2 id="article85" class="sr-only" tabindex="-1">제85조 (대가의 지급) <a class="header-anchor" href="#article85" aria-label="Permalink to &quot;제85조 (대가의 지급) {#article85 .sr-only}&quot;">​</a></h2><p><strong>제85조(대가의 지급)</strong> ① 대표이사 또는 그 위임을 맡은 자는 공사, 제조, 구매, 용역 기타 지출의 원인이 되는 계약에 있어서는 검사를 완료한 후 계약대상자의 청구를 받은 날로부터 7일(공휴일, 토요일 제외) 이내에 계약의 대가를 지급하여야 한다. &lt;개정 2014. 12. 29.&gt;<br> ② 제1항 본문의 경우 계약대상자와의 합의에 의하여 7일을 초과하지 아니하는 범위 내에 대가의 지급기간을 연장할 수 있는 특약을 정할 수 있다. &lt;개정 2014. 12. 29.&gt;</p><h2 id="article86" class="sr-only" tabindex="-1">제86조 (하자담보책임기간) <a class="header-anchor" href="#article86" aria-label="Permalink to &quot;제86조 (하자담보책임기간) {#article86 .sr-only}&quot;">​</a></h2><p><strong>제86조(하자담보책임기간)</strong> ① 대표이사 또는 그 위임을 받은 자는 재단의 도급계약을 체결할 때에는 그 목적물을 인수한 날과 준공검사를 완료한 날 중에서 먼저 도래한 날로부터 1년 이상 10년 이하의 범위 내에서 하자보수를 보증하기 위한 하자담보 책임기간을 정하여야 한다.<br> ② 공사의 성질상 하자보수를 필요로 하지 아니하는 공사의 경우에는 하자담보 책임기간을 정하지 아니한다.</p><h2 id="article87" class="sr-only" tabindex="-1">제87조 (하자보수보증금) <a class="header-anchor" href="#article87" aria-label="Permalink to &quot;제87조 (하자보수보증금) {#article87 .sr-only}&quot;">​</a></h2><p><strong>제87조(하자보수보증금)</strong> ① 대표이사 또는 그 위임을 받은 자는 공사의 도급계약에 있어서 그 공사의 하자보수를 보증하기 위하여 계약상대자로 하여금 공사대가의 최종지출시 까지 하자 보수보증금을 납부하게 하여야 한다.<br> ② 하자담보의 책임기간 및 보증내용 등 필요한 사항은 지방자치단체를 당사자로 하는 계약에 관한 법률을 준용한다.</p><h2 id="article88" class="sr-only" tabindex="-1">제88조 (하자보수보증금의 직접사용) <a class="header-anchor" href="#article88" aria-label="Permalink to &quot;제88조 (하자보수보증금의 직접사용) {#article88 .sr-only}&quot;">​</a></h2><p><strong>제88조(하자보수보증금의 직접사용)</strong> ① 대표이사 또는 그 위임을 받은 자는 공사 등에 하자가 발생한 경우 하자에 대한 보수를 당해업체에 요청하되, 만약 하자보수를 이행치 않을 시 당해 하자보수보증금을 그 하자의 보수를 위하여 직접 사용할 수 있다.<br> ② 제1항의 경우에 직접 사용한 하자보수보증금은 재단에 귀속된 것으로 본다.</p><h2 id="article89" class="sr-only" tabindex="-1">제89조 (보증금의 귀속절차) <a class="header-anchor" href="#article89" aria-label="Permalink to &quot;제89조 (보증금의 귀속절차) {#article89 .sr-only}&quot;">​</a></h2><p><strong>제89조(보증금의 귀속절차)</strong> 대표이사 또는 그 위임을 받은 자는 납부된 보증금을 재단에 귀속시켜야 할 사유가 발생한 경우 계약대상자에게 계약의 해지 또는 해제의 통지 등 필요한 조치를 취하고 당해 보증금을 다음 각호와 같이 처리하여야 한다.</p><ol><li>현금의 경우에는 수입금으로 징수 조치한다.</li><li>유가증권은 재단의 소유유가증권으로 귀속 조치한다. 이 경우 등록 국채에 있어서는 그 뜻을 유가증권 취급점에 통지하여야 한다.</li><li>보증보험증권 등인 경우에는 관계보증기관에 그 뜻을 통지하고 당해 보증금을 수입금으로 징수함에 있어서 필요한 조치를 취한다.</li><li>정기예금증서 등인 경우에는 당해 금융기관에 그 뜻을 통지하고 당해 보증금을 수입금으로 징수 조치한다.</li></ol><h2 id="article90" class="sr-only" tabindex="-1">제90조 (장기계속계약) <a class="header-anchor" href="#article90" aria-label="Permalink to &quot;제90조 (장기계속계약) {#article90 .sr-only}&quot;">​</a></h2><p><strong>제90조(장기계속계약)</strong> 대표이사 또는 그 위임을 받은 자는 임대차ㆍ운송ㆍ보관ㆍ전기ㆍ가스ㆍ수도의 공급 기타 그 성질상 수년간 계속하여 존속할 필요가 있거나 이행에 수년을 요하는 계약에 있어서는 장기계속계약을 체결할 수 있다. 이 경우에는 각 회계연도 예산의 범위 안에서 당해 계약을 이행하게 하여야 한다.</p><h2 id="article91" class="sr-only" tabindex="-1">제91조 (단가계약) <a class="header-anchor" href="#article91" aria-label="Permalink to &quot;제91조 (단가계약) {#article91 .sr-only}&quot;">​</a></h2><p><strong>제91조(단가계약)</strong> 대표이사 또는 그 위임을 받은 자는 일정기간 계속하여 제조ㆍ수리ㆍ가공ㆍ매매ㆍ공급ㆍ사용 등의 계약을 할 필요가 있을 때에는 당해연도의 예산범위 안에서 단가에 대하여 계약을 체결 할 수 있다.</p><h2 id="article92" class="sr-only" tabindex="-1">제92조 (개산계약 및 사후원가검토조건부 계약) <a class="header-anchor" href="#article92" aria-label="Permalink to &quot;제92조 (개산계약 및 사후원가검토조건부 계약) {#article92 .sr-only}&quot;">​</a></h2><p><strong>제92조(개산계약 및 사후원가검토조건부 계약)</strong> ① 대표이사 또는 그 위임을 받은 자는 개발 시 제품의 제조계약, 시험ㆍ조사ㆍ연구용역 계약, 법령 규정에 의한 정부의 위탁 또는 대행계약에 있어서 미리 예정가격을 정할 수 없을 때에는 개산계약을 체결할 수 있다.<br> ② 대표이사 또는 그 위임을 받은 자는 제1항의 규정에 의하여 개산계약을 체결하고자 할 때에는 미리 개산가격을 결정하여야 하며 계약의 이행이 완료된 후 거래실례가격 또는 원가계산에 의한 가격 등에 따라 정산하여야 한다.</p><h2 id="article93" class="sr-only" tabindex="-1">제93조 (지연배상금) <a class="header-anchor" href="#article93" aria-label="Permalink to &quot;제93조 (지연배상금) {#article93 .sr-only}&quot;">​</a></h2><p><strong>제93조(지연배상금)</strong> 대표이사 또는 그 위임을 받은 자는 지출의 원인이 되는 계약을 체결함에 있어서 계약상대자(국가ㆍ지방자치단체를 제외한다)가 계약상의 의무를 지체한 때 지연배상금은 공사는 1000분의 1, 물품의 제조, 구매는 1000분의 1.5, 물품의 수리ㆍ가공ㆍ대여ㆍ용역 및 기타는 1000분의 2.5, 운송보관은 1000분의 5를 지체일수에 곱한 금액을 계약 상대자로 하여금 현금으로 납부하게 하여야 한다. 이 경우 계약상대자에게 책임 없는 사유로 계약이행이 지체되었다고 인정될 때에는 그 해당일수를 지체일수에 산입하지 아니 한다. &lt;개정 2014. 12. 29.&gt;</p><h2 id="article94" class="sr-only" tabindex="-1">제94조 (계약의 해제ㆍ해지) <a class="header-anchor" href="#article94" aria-label="Permalink to &quot;제94조 (계약의 해제ㆍ해지) {#article94 .sr-only}&quot;">​</a></h2><p><strong>제94조(계약의 해제ㆍ해지)</strong> ① 대표이사 또는 그 위임을 받은 자는 계약보증금을 재단에 귀속시키는 경우에는 계약에 특별히 정한 것이 없는 한 당해 계약을 해제 또는 해지하고 계약상대자에게 그 사유를 통지하여야 한다.<br> ② 지연배상금 징수사유가 발생하고 그 금액이 계약보증금상당액에 달하는 경우로서 계약자의 귀책사유로 계약을 수행할 가능성이 없음이 명백하다고 인정될 때에는 대표이사 또는 그 위임을 받은 자는 계약보증금을 재단에 귀속시키고 당해 계약을 해제 또는 해지할 수 있다. &lt;개정 2014. 12. 29.&gt;</p><h2 id="article95" class="sr-only" tabindex="-1">제95조 (부정당업자의 입찰참가자격 제한) <a class="header-anchor" href="#article95" aria-label="Permalink to &quot;제95조 (부정당업자의 입찰참가자격 제한) {#article95 .sr-only}&quot;">​</a></h2><p><strong>제95조(부정당업자의 입찰참가자격 제한)</strong> ① 대표이사는 공정한 경쟁이나 계약의 적정한 이행을 해칠 것이 명백하다고 판단되는 자에 대해서는 2년의 범위에서 입찰참가자격을 제한할 수 있다. 이 경우 불가피한 사유가 있는 것으로 인정되는 경우를 제외하고는 &quot;지방자치단체를 당사자로 하는 계약에 관한 법률&quot; 제32조에 따른 계약심의위원회에서 그 입찰참가자격 제한 여부에 관하여 심의할 수 있도록 지방자치단체의 장에게 요청하여야 한다. &lt;개정 2015. 9. 21.&gt;<br> ② 대표이사는 제1항에 따라 입찰참가자격을 제한받은 자와 수의계약을 체결해서는 아니 된다. 다만, 제1항에 따라 입찰참가자격을 제한받은 자 외에는 적합한 시공자·제조자가 존재하지 아니하는 등 부득이한 사유가 있는 경우에는 그러하지 아니하다. &lt;개정 2015. 9. 21.&gt;<br> ③ 제1항에서 제2항까지의 규정에 따른 계약의 기준 및 절차와 입찰참가자격의 제한 등에 관하여 그 밖에 필요한 사항은 대통령령에 따른다. &lt;개정 2015. 9. 21.&gt;</p><h2 id="제9장-내부감사" tabindex="-1">제9장 내부감사 <a class="header-anchor" href="#제9장-내부감사" aria-label="Permalink to &quot;제9장 내부감사&quot;">​</a></h2><h2 id="article96" class="sr-only" tabindex="-1">제96조 (내부감사) <a class="header-anchor" href="#article96" aria-label="Permalink to &quot;제96조 (내부감사) {#article96 .sr-only}&quot;">​</a></h2><p><strong>제96조(내부감사)</strong> 재단 각 부서의 수입, 지출 및 계산에 있어 부정, 오류, 부당처리의 유무를 가려내고 재발 방지를 위하여 내부감사를 실시한다.</p><h2 id="article97" class="sr-only" tabindex="-1">제97조 (감사담당자) <a class="header-anchor" href="#article97" aria-label="Permalink to &quot;제97조 (감사담당자) {#article97 .sr-only}&quot;">​</a></h2><p><strong>제97조(감사담당자)</strong> 내부 회계감사의 담당자는 직제규정이 정하는 바에 의한다.</p><h2 id="article98" class="sr-only" tabindex="-1">제98조 (감사방법) <a class="header-anchor" href="#article98" aria-label="Permalink to &quot;제98조 (감사방법) {#article98 .sr-only}&quot;">​</a></h2><p><strong>제98조(감사방법)</strong> 내부감사의 감사방법 등에 대하여는 감사규정이 정하는 바에 의한다.</p><h2 id="article99" class="sr-only" tabindex="-1">제99조 (타규정과의 관계) <a class="header-anchor" href="#article99" aria-label="Permalink to &quot;제99조 (타규정과의 관계) {#article99 .sr-only}&quot;">​</a></h2><p><strong>제99조(타규정과의 관계)</strong> ① 내부회계감사에 있어서 감사규정과 이 규정과의 상호 적용에 대하여 이의가 있을 때에는 이 규정이 우선하는 것으로 간주한다.<br> ② 내부회계감사 이외의 문제로 타 규정과 상충될 때에는 대표이사의 결정에 따른다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(시행일) 이 규정은 2004년 3월 12일부터 시행한다.<br> 제2조(경과조치) 이 규정 시행 이전에 재단설립과 관련하여 확정된 원인행위 및 회계처리 사항은 이 규정에 의하여 처리된 것으로 본다.<br> 제3조(겸직규정) 회계, 예산, 결산, 계약 등 이규정의 해당 기능별로 독립의 업무를 담당토록 되어 있는 각 조항은 정원의 과소 등으로 겸직이 불가피한 경우에는 이를 적용하지 아니할 수 있다.<br> 제4조(위임규정) 이 규정의 시행과 관련하여 필요한 사항은 별도의 시행내규를 제정하여 적용할 수 있다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2004. 4. 27.&gt;<br> 이 규정은 2004년 4월 27일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2006. 2. 21.&gt;<br> 이 규정은 2006년 2월 21일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2007. 12. 21.&gt;<br> 이 규정은 2007년 12월 21일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2008. 3. 28.&gt;<br> 제1조(시행일) 이 규정은 2008년 3월 28일부터 시행한다.<br> 제2조(경과조치) 이 규정의 시행 전에 대표이사 방침에 의해 시행된 사항은 이 규정에 의하여 시행된 것으로 본다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2010. 9. 1.&gt;<br> 제1조(시행일) 이 규정은 2010년 9월 1일부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2014. 3. 31.&gt;<br> 제1조(시행일) 이 규정은 2014년 3월 31일부터 시행한다.</p><h2 id="addendum8" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum8" aria-label="Permalink to &quot;부칙 {#addendum8 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2014. 12. 29.&gt;<br> 제1조(시행일) 이 규정은 2014년 12월 29일부터 시행한다.</p><h2 id="addendum9" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum9" aria-label="Permalink to &quot;부칙 {#addendum9 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2015. 9. 21.&gt;<br> 제1조(시행일) 이 규정은 2015년 9월 21일부터 시행한다.</p><h2 id="addendum10" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum10" aria-label="Permalink to &quot;부칙 {#addendum10 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2016. 3. 29.&gt;<br> 제1조(시행일) 이 규정은 2016년 3월 29일부터 시행한다.</p><h2 id="addendum11" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum11" aria-label="Permalink to &quot;부칙 {#addendum11 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2016. 10. 7.&gt;<br> 제1조(시행일) 이 규정은 2016년 10월 7일부터 시행한다.</p><h2 id="addendum12" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum12" aria-label="Permalink to &quot;부칙 {#addendum12 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 11. 1.&gt;<br> 제1조(시행일) 이 규정은 이사회의 승인을 얻은 날로부터 시행한다.</p><h2 id="addendum13" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum13" aria-label="Permalink to &quot;부칙 {#addendum13 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2021. 12. 29.&gt;<br> 제1조(시행일) 이 규정은 이사회의 승인을 얻은 날로부터 시행한다.</p><p><strong>[별표 1]</strong> &lt;신설 2016. 10. 7.&gt;</p><p>부당계약 조건 10개 항목</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:618px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">① 과업지시서, 특수조건 등 계약서류에 갑을 용어 사용</p><p style="margin:0;text-align:left;">② 과업내용 해석 상 이견 발생 시 산하기관 의견 강요</p><p style="margin:0;text-align:left;">③ 과업 수행 중 계약내용 변경사유 발생 시 계약금액 조정 협의 제한</p><p style="margin:0;text-align:left;">④ 계약서에 기재하지 않은 내용에 대해 추가적인 과업지시</p><p style="margin:0;text-align:left;">⑤ 계약기간 이후 계약상대자에게 추가적인 과업지시</p><p style="margin:0;text-align:left;">⑥ 포괄적, 불명확한 사유에 의한 계약해지</p><p style="margin:0;text-align:left;">⑦ 그 밖에 산하기관이 요구하는 사항’ 등 포괄적 과업지시</p><p style="margin:0;text-align:left;">⑧ 계약진행 중 문제 발생 시 책임소재 구분 없이 모든 책임 전가</p><p style="margin:0;text-align:left;">⑨ 산출내역서에 명시되지 않은 비용에 대해 계약상대자 부담</p><p style="margin:0;text-align:left;">⑩ 협상계약 제안서평가위원회 평가결과 비공개</p></th></tr></table>`,261)]))}const u=r(o,[["render",i]]);export{g as __pageData,u as default};
